"""Build the five navigable pilot pages from the saved scientific result."""
from pathlib import Path
from html import escape
import json

ROOT=Path(__file__).resolve().parents[2]
DATA=json.loads((ROOT/'research/pilot/results.json').read_text())
CASES={c['site']['id']:c for c in DATA['cases']}
PAGES=[('start','The question'),('regions','Explore regions'),('hypotheses','Compare histories'),('method','How we tested'),('results','Results')]


def url(page):return '/research/pilot'+('' if page=='start' else '/'+page)
def n(value):return f'{value:.2f}'
def pct(value):return f'{value:.0%}'
def case(id,h='150'):return CASES[id]['baseline'][h]


def page(stem,title,lead,body):
    index=[p[0] for p in PAGES].index(stem)
    nav=''.join(f'<a href="{url(p)}"'+(' aria-current="page"' if p==stem else '')+f'>{i+1}. {label}</a>' for i,(p,label) in enumerate(PAGES))
    previous=f'<a href="{url(PAGES[index-1][0])}">← {PAGES[index-1][1]}</a>' if index else '<a href="/">← Project overview</a>'
    following=f'<a href="{url(PAGES[index+1][0])}">{PAGES[index+1][1]} →</a>' if index<4 else '<a href="/research/pilot/regions">Return to the observations →</a>'
    scripts='<script defer src="/assets/plotly.min.js"></script><script defer src="/assets/pilot.js"></script>' if stem=='regions' else ''
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} · Mars regional study</title><link rel="stylesheet" href="/assets/research.css"><link rel="stylesheet" href="/assets/workspace.css"><link rel="stylesheet" href="/assets/pilot.css">{scripts}</head><body class="workspace pilot"><a class="skip" href="#content">Skip to content</a><header class="workspace-header"><a class="wordmark" href="/"><i></i><span>Mars research<small>CHARLOTTE CROCICCHIA</small></span></a><nav aria-label="Main navigation"><a href="/">Overview</a><a href="/research/pilot" aria-current="page">Study</a><a href="/research/hypotheses">Ideas</a><a href="/research/data">Data</a><a href="/research/tests">Tests</a><a href="/research/library">Library</a><a href="/atmosphere">Atmosphere</a></nav></header><div class="study-bar"><div><strong>01 / THE MAGNETIC RECORD</strong><nav aria-label="Study chapters">{nav}</nav></div></div><main id="content"><div class="page-intro"><p class="eyebrow">REGIONAL PILOT · {index+1:02d} / 05</p><h1>{title}</h1><p class="lead">{lead}</p></div>{body}<nav class="study-pager" aria-label="Previous and next chapter">{previous}{following}</nav></main><footer><span>A personal research project by Charlotte Crocicchia.<br>Exploratory analysis · 24 September 2026 · Prepared with AI assistance.</span><a href="https://github.com/charlottecrocicchia-netizen/mars-wind-lab">Code, data provenance & research notes ↗</a></footer></body></html>'''


start='''<div class="study-layout"><div><p class="study-kicker">OUR WORKING QUESTION</p><h2>Different ancient fields,<br>or different ways to preserve them?</h2><p>A magnetic map records a long history: rock formation, cooling, impacts, mineral growth and later alteration. Before interpreting the north–south contrast, we test how reliably a regional magnetic contrast can describe that history.</p><p>This first study compares four craters in three regions, plus a flagged window near Ladon. It tests the measurements and their sensitivity before selecting a physical explanation.</p><a class="button" href="/research/pilot/regions">Follow the study →</a></div><aside class="study-box"><p class="eyebrow">THE FIRST RESULT</p><h2>The reference terrain can change the answer.</h2><p>Newton looks weaker than its surroundings. Compare the same mapped surface units, and that contrast reverses. Schiaparelli changes sign with observation altitude.</p><p>These are useful constraints on how to construct a physical test. They do not identify the cause of the crustal dichotomy.</p><a href="/research/pilot/results">Go directly to the results →</a></aside></div><div class="study-steps"><a href="/research/pilot/regions"><span class="study-kicker">OBSERVE</span><h2>Five regional windows</h2><p>Inspect the same field model at three altitudes, with terrain and mineral context.</p></a><a href="/research/pilot/hypotheses"><span class="study-kicker">EXPLAIN</span><h2>Three recording histories</h2><p>What would preserved, thermally reset or chemically rebuilt rocks look like?</p></a><a href="/research/pilot/method"><span class="study-kicker">VERIFY</span><h2>Every choice is visible</h2><p>Reference rings, geology, sensitivity tests, source limitations and downloadable calculations.</p></a></div><p class="pilot-note">The regional cases were selected from published hydrothermal research. They are not a representative sample of Mars or independent north–south controls. Orbital magnetic field, rock magnetization and ancient field intensity are different quantities.</p>'''

regions='''<div class="map-controls"><label>Region<select id="pilotRegion"><option value="newton">Newton · Eridania</option><option value="copernicus">Copernicus · Eridania</option><option value="huygens">Huygens</option><option value="schiaparelli">Schiaparelli</option><option value="ladon">Ladon window · flagged geometry</option></select></label><label>Map layer<select id="pilotLayer"><option value="field">Orbital magnetic field</option><option value="topography">MOLA elevation</option></select></label><label>Magnetic altitude<select id="pilotAltitude"><option value="130">130 km</option><option value="150" selected>150 km</option><option value="400">400 km</option></select></label><label class="check-label"><input type="checkbox" id="pilotMinerals">Show mineral detections</label></div><p id="pilotStatus" role="status">Loading the saved regional calculations…</p><div class="region-visual"><div class="plot-panel"><div id="pilotMap" class="pilot-map" role="img" aria-label="Regional field or elevation map with comparison circles"></div><p id="pilotMapLegend" class="mineral-legend" hidden></p><p>Solid line: sampled interior (0.8 R). Dotted line: catalog rim (R). Dashed lines: reference ring (1.2–2 R). R is half the catalog diameter.</p></div><aside class="region-metrics" id="pilotMetrics" aria-live="polite"></aside></div><p class="pilot-note" id="pilotCaution"></p><section><div class="section-row"><div><p class="eyebrow">FOLLOW THE CONTRAST</p><h2>How does the field change across this region?</h2></div><a class="study-source" href="/research/pilot/results">Compare all regions →</a></div><div class="plot-panel"><div id="pilotProfile" class="pilot-chart" role="img" aria-label="Radial magnetic field profiles at three altitudes"></div><p>Area-weighted annular means from one magnetic model. Smooth adjacent samples are not independent measurements. The gray line marks the catalog rim.</p></div></section><details class="method-drawer"><summary>Inspect the geology comparison</summary><p>Outside means are reweighted to the interior's surface map-unit proportions, using only units present on both sides. This changes the comparison population. It does not control deep lithology, alteration age or impact heating.</p><div id="pilotGeology"></div></details><details class="method-drawer" id="morphDrawer"><summary>Inspect the crater-depth diagnostic</summary><div id="pilotMorphology" class="pilot-chart" role="img" aria-label="MOLA median radial topographic profile"></div><p id="pilotMorphNote"></p><p>Published-method transfer using the local 4 ppd MOLA grid and fixed catalog rims. The band shows the middle half of azimuthal elevations, not an error bar. The original joint inversion has not been reproduced.</p></details><details class="method-drawer"><summary>What the mineral markers mean</summary><p>Each marker is a 2° cell containing at least one MOCAAS mineral detection. A blank area is unknown. These points are context only and are not used as a wet/dry variable in the calculation.</p><div id="pilotMineralTable"></div><p>CRISM and OMEGA detections are unioned by class. The coordinate convention has not been independently validated at native deposit scale; no precise spatial association is inferred.</p><a class="study-source" href="/research/data?view=water">Open all mineral maps →</a></details>'''

hypotheses='''<div class="study-takeaway"><p>This pilot does not distinguish the three histories.</p><small>The regional calculation measures an orbital contrast. It cannot date a magnetic component or identify the mineral generation carrying it.</small></div><article class="hypothesis-card" id="retention"><div><span class="study-kicker">H1 / PRESERVATION</span><h2>An early record survives</h2><p>Ancient carriers retain a remanence acquired before later geological events.</p><a class="study-source" href="/research/data?view=laboratory&amp;sample=alh-84001">Inspect ALH 84001 →</a></div><div><dl><dt>What this history must explain</dt><dd>The age and stability of an old magnetic component, the surviving carrier population and later heating or alteration.</dd><dt>What could contradict it</dt><dd>Evidence that the carrier formed after the proposed recording event, or that subsequent conditions destroyed that component.</dd><dt>What we find here</dt><dd>Lower orbital amplitudes do not establish loss of remanence. Source geometry, thickness and vector cancellation remain alternatives.</dd></dl><p class="hypothesis-outcome">Status: unresolved. No regional survival history has been fitted.</p></div></article><article class="hypothesis-card" id="thermal"><div><span class="study-kicker">H2 / THERMAL RESETTING</span><h2>A later event rewrites part of the record</h2><p>Heating or shock changes which grains retain an older component; cooling can record another field.</p><a class="study-source" href="/research/data?view=laboratory&amp;sample=tissint">Inspect Tissint →</a></div><div><dl><dt>What this history must explain</dt><dd>A measured blocking spectrum and time–temperature path compatible with both reset and preserved components.</dd><dt>What could contradict it</dt><dd>A thermal history unable to reset the component, or one that would erase independent mineral or isotopic evidence that survives.</dd><dt>What we find here</dt><dd>Copernicus and Huygens remain weaker than their comparison rings across the tested choices, but no temperatures or reset ages follow from those ratios.</dd></dl><p class="hypothesis-outcome">Status: unresolved. Present-day thermal endpoints are not a history of heating.</p></div></article><article class="hypothesis-card" id="chemical"><div><span class="study-kicker">H3 / CHEMICAL REBUILDING</span><h2>Water–rock reactions change the recorder</h2><p>Alteration can create, transform or destroy magnetic carriers. The outcome also depends on the field present during the reaction.</p><a class="study-source" href="/research/data?view=laboratory&amp;sample=lafayette">Inspect Lafayette's separate clocks →</a></div><div><dl><dt>What this history must explain</dt><dd>A dated mineral generation, reaction conditions and a magnetic component linked to that generation.</dd><dt>What could contradict it</dt><dd>A remanence older than the mineral carrying it, or a reaction path that cannot produce the required carrier under independently constrained conditions.</dd><dt>What we find here</dt><dd>Surface mineral detections alone cannot establish alteration of deep magnetic sources. The missing survey/exposure mask prevents a controlled mineral–field association test.</dd></dl><p class="hypothesis-outcome">Status: unresolved. No chemical acquisition efficiency or alteration age is inferred.</p></div></article><section><h2>How meteorites constrain these histories</h2><div class="table-scroll"><table><thead><tr><th>Evidence</th><th>Useful constraint</th><th>What it does not supply</th></tr></thead><tbody><tr><td><a href="/research/data?view=laboratory&amp;sample=mil-03346">MIL 03346</a></td><td>Interior/fusion-crust and component tests help assess a Martian record.</td><td>A unique source crater or proof of a late core dynamo; local crustal fields remain possible.</td></tr><tr><td><a href="/research/data?view=laboratory&amp;sample=tissint">Tissint</a></td><td>A proposed post-shock recording event separates remanence from crystallization.</td><td>The acquisition age of every Martian magnetic anomaly.</td></tr><tr><td><a href="/research/data?view=laboratory&amp;sample=lafayette">Lafayette</a></td><td>An alteration date of 742 ± 15 Ma (2σ) supplies a separate fluid-related clock.</td><td>The age of its magnetic component, or a global ocean at that time.</td></tr><tr><td><a href="/research/data?view=laboratory&amp;sample=alh-84001">ALH 84001</a></td><td>Ancient components, carrier-scale measurements and event ordering.</td><td>An unambiguous hemisphere or absolute Martian laboratory orientation.</td></tr></tbody></table></div><p class="pilot-note">These are constraints from published studies, not new paleointensities fitted in this pilot. Primary and secondary refer to a geological event; terrestrial contamination is a separate problem. Unknown meteorite source locations remain unknown.</p><p class="study-source"><a href="https://doi.org/10.1029/2021JE006856">Volk, Fu et al. (2021)</a> · <a href="https://doi.org/10.1111/maps.12172">Gattacceca et al. (2013)</a> · <a href="https://doi.org/10.7185/geochemlet.2443">Tremblay et al. (2024)</a> · <a href="https://doi.org/10.1126/sciadv.ade9071">Steele, Fu et al. (2023)</a> · <a href="https://doi.org/10.1007/s11214-025-01194-2">Gattacceca, Maurel, Weiss et al. (2025)</a></p></section><section class="study-box"><h2>Where does the dichotomy fit?</h2><p>These histories can occur within impact-driven or internally generated crustal evolution. The pilot tests the reliability of one part of that larger argument: interpreting the magnetic record. It does not rank those global origin scenarios.</p><a href="/research/hypotheses">Return to the global hypothesis framework →</a></section>'''

max_error=max(c['absolute_error_nT'] for c in DATA['numerical_checks'])
method=f'''<div class="method-steps"><section class="method-step"><h2>Choose the cases before calculating the contrasts</h2><p>The protocol defines four primary craters and a separate Ladon window, selected from published hydrothermal candidate regions. Newton and Copernicus are part of the same regional setting. Selection is literature-led and exploratory, not random or preregistered.</p><p>Four geometries use the IAU/USGS Gazetteer, MDIM 2.1, planetocentric east-positive coordinates. Ladon's catalog entry is flagged “Misidentified” in the author-hosted revised catalog; it is used only for sensitivity, not as a validated crater.</p></section><section class="method-step"><h2>Recalculate the same observable at three altitudes</h2><p>Evaluate the full degree-134 Langlais et al. (2019) magnetic model at 130, 150 and 400 km above its 3393.5 km reference sphere. Use the magnitude of the three-component field at each point, then area-weight means with cos(latitude). A 0.5° sampling grid is numerical quadrature, not independent observations or true 30 km magnetic resolution.</p><p>Four direct evaluations reproduce the existing rounded atlas to within {max_error:.6f} nT. This is a numerical consistency check using the same model, not independent geophysical validation.</p><p class="study-source"><a href="https://doi.org/10.1029/2018JE005854">Magnetic model: Langlais et al. (2019)</a></p></section><section class="method-step"><h2>Transfer a published topographic diagnostic</h2><p>Sample the 4 ppd MOLA elevation grid along rays every 30° out to 2 R. Take the median over azimuth, then calculate depth from the minimum within 0.2 R to the median at 1–1.2 R; divide by the diameter.</p><p>This follows the radial recipe in Mittelholz et al. (2025), with fixed catalog rims, a different working grid and no visual rim adjustment. It is a method transfer, not an exact numerical reproduction. The paper's joint density–magnetization inversion and gravity selection have not been rerun. Its regularization also favours related density and magnetization patterns.</p><p class="study-source"><a href="https://doi.org/10.1029/2024JE008832">Published method and study context</a> · <a href="https://pds-geosciences.wustl.edu/missions/mgs/megdr.html">MOLA archive</a></p></section><section class="method-step"><h2>Make the reference comparison explicit</h2><p>The baseline ratio is mean |B| inside 0.8 R divided by mean |B| in the ring 1.2–2 R. The gap avoids directly mixing the rim into both samples. The surrounding ring is a local reference, not a proven unaltered control.</p><p>For a second comparison, retain surface map units present inside and outside, then reweight their outside means to the interior's unit proportions. Report how much interior area remains. Map units are broad surface classifications, not precise ages or deep magnetic lithologies; they can also be consequences of the event being studied. This is descriptive standardization, not a causal adjustment.</p><p>We separately exclude interiors of other catalog craters ≥150 km from the reference ring, omitting entries labelled misidentified. This does not remove their ejecta, intrusive heating or buried impacts.</p><p class="study-source"><a href="https://doi.org/10.3133/sim3292">USGS geologic map</a> · <a href="https://github.com/alagain/martian_crater_database/tree/ccd5de7bbc6525d25d746332b4a1e58ba1f72680/Global">Versioned crater catalog</a></p></section><section class="method-step"><h2>Try to break the interpretation</h2><p>For every window, run 81 combinations: three altitudes × three inside radii (0.6, 0.8, 1 R) × three reference rings (1.2–1.8, 1.2–2, 1.5–2.5 R) × three radius factors (0.9, 1, 1.1). Repeat the map-unit calculation for each combination. At the baseline, omit each of eight 45° sectors in turn.</p><p>The displayed envelopes are ranges over chosen analysis settings, not confidence intervals. Altitudes share model coefficients; nearby grid points are correlated. We do not use pixel counts as replicate counts and do not compute p-values or mechanism probabilities. No physically calibrated model exists here to score on held-out regions.</p></section></div><section class="study-box"><p class="eyebrow">OBSERVATION COVERAGE AUDIT</p><h2>Why there is no “water causes weak magnetism” test</h2><p>The acquired MOCAAS archive contains ten mineral rasters. Its paper discusses coverage maps, but no usable survey/exposure mask was found in the downloaded bundle or the project's listed global downloads. A general instrument footprint would still not encode dust, burial, detection sensitivity or which observations were analysed.</p><p>We therefore use occupied 2° cells as presence-only context. They never define wet and dry groups. Surface signatures do not automatically sample deep magnetic sources.</p><p class="study-source"><a href="https://doi.org/10.1016/j.icarus.2022.115164">Carter et al. (2023), coverage and detection limits</a> · <a href="https://www.ias.u-psud.fr/moccas/">MOCAAS downloads</a></p></section><details class="method-drawer"><summary>Reproduce the complete saved study</summary><p>From the repository root, with the base observation inputs already acquired:</p><pre>pip install -e '.[observations,research,test]'
python scripts/data/acquire_pilot.py
python scripts/data/build_pilot.py
python scripts/research/render_pilot.py
pytest -q -m 'not integration'</pre><p>On a new installation, first follow the base acquisition instructions in the README (several GB). The pilot build performs no network requests. Output records source, protocol and code SHA-256 hashes. Raw third-party archives remain local.</p><div class="download-row"><a href="/research/files/pilot/protocol.json" download>Protocol JSON ↓</a><a href="/research/files/pilot/sources.json" download>Additional source manifest ↓</a><a href="/research/files/pilot/results.json" download>Results & provenance ↓</a><a href="https://github.com/charlottecrocicchia-netizen/mars-wind-lab/blob/main/scripts/data/build_pilot.py">Analysis code ↗</a></div></details>'''

table_rows=''.join(f'''<tr><td><a href="/research/pilot/regions?region={c['site']['id']}">{c['site']['name']}</a>{' <small>(sensitivity only)</small>' if c['site']['id']=='ladon' else ''}</td><td>{n(c['baseline']['150']['ratio'])}</td><td>{n(c['baseline']['150']['matched_ratio'])}</td><td>{pct(c['baseline']['150']['common_support_fraction'])}</td><td>{n(c['summary']['ratio_min'])}–{n(c['summary']['ratio_max'])}</td></tr>''' for c in DATA['cases'])
results=f'''<div class="study-takeaway"><p>Two contrasts are stable across the tested choices. Two depend strongly on how we observe or compare them.</p><small>This helps choose the next physical tests. It does not identify thermal resetting, chemical rebuilding or the origin of the dichotomy.</small></div><div class="result-list"><article class="result-item"><span class="study-kicker">01 / GEOLOGY MATTERS</span><h2>Newton reverses</h2><p>The inside/ring ratio changes from <strong>{n(case('newton')['ratio'])}</strong> to <strong>{n(case('newton')['matched_ratio'])}</strong> after standardizing the surface map units at 150 km. The surface-unit mix can change the descriptive conclusion.</p><a class="study-source" href="/research/pilot/regions?region=newton">Inspect Newton →</a></article><article class="result-item"><span class="study-kicker">02 / SCALE MATTERS</span><h2>Schiaparelli crosses unity</h2><p>The unadjusted ratio is <strong>{n(case('schiaparelli','130')['ratio'])}</strong> at 130 km and <strong>{n(case('schiaparelli','400')['ratio'])}</strong> at 400 km. Only <strong>{pct(case('schiaparelli')['common_support_fraction'])}</strong> of its interior remains in the same-unit comparison.</p><a class="study-source" href="/research/pilot/regions?region=schiaparelli">Inspect Schiaparelli →</a></article><article class="result-item"><span class="study-kicker">03 / MORE STABLE TARGETS</span><h2>Copernicus & Huygens stay lower</h2><p>Their unadjusted and same-unit ratios remain below one across all 81 tested settings each. These are priorities for mechanism-specific follow-up; a persistent weak-field contrast alone does not reveal its cause.</p><a class="study-source" href="/research/pilot/regions?region=huygens">Inspect Huygens →</a></article></div><section><h2>The numbers, with their comparison populations</h2><p class="pilot-note">A ratio of 1 means equal mean orbital field; 0.5 means the interior mean is half the reference mean. It is not the fraction of remanence remaining in a rock.</p><div class="table-scroll"><table><thead><tr><th>Case</th><th>Raw ratio<br>150 km</th><th>Same surface units<br>150 km</th><th>Interior area<br>retained</th><th>Raw sensitivity range<br>all altitudes & geometries</th></tr></thead><tbody>{table_rows}</tbody></table></div><p class="table-caption">Same-unit values use a different reference mixture and, for Schiaparelli, a restricted interior. Ranges are not confidence intervals. Ladon is excluded from primary crater conclusions because the catalog geometry is flagged.</p></section><section><h2>What the hypothesis tests actually decide</h2><div class="table-scroll"><table><thead><tr><th>Claim under test</th><th>Outcome</th><th>Interpretation</th></tr></thead><tbody><tr><td>Every primary crater has a lower interior orbital field.</td><td>True for the selected 150 km baseline; not stable across all comparisons.</td><td>Schiaparelli changes sign with altitude; Newton changes sign with map-unit standardization.</td></tr><tr><td>Every primary crater has a higher interior orbital field.</td><td>Contradicted by all four baseline contrasts.</td><td>This rejects only that restrictive observable rule.</td></tr><tr><td>A weaker orbital field proves destruction of ancient remanence.</td><td>Not identifiable from these data.</td><td>Source thickness, geometry, cancellation, initial field and carrier histories can produce similar observations.</td></tr><tr><td>Preservation, thermal resetting or chemical rebuilding is uniquely preferred.</td><td>No physical history selected.</td><td>The pilot has no joint forward fit, dated regional carrier histories or coverage-controlled mineral test.</td></tr></tbody></table></div></section><figure class="result-figure"><a href="/research/files/pilot/regional_pilot.png"><img src="/research/files/pilot/regional_pilot.png" alt="Four-panel scientific figure comparing regional field ratios, radial field profiles, surface-geology standardization and MOLA topographic profiles."></a><figcaption>Project-computed results from the saved protocol. Panel A varies analysis geometry at each altitude; panel C changes the comparison population. Open the image for full resolution.</figcaption></figure><div class="download-row"><a href="/research/files/pilot/regional_pilot.png" download>Figure · PNG ↓</a><a href="/research/files/pilot/regional_pilot.svg" download>Figure · SVG ↓</a><a href="/research/files/pilot/contrasts.csv" download>All 405 settings · CSV ↓</a><a href="/research/files/pilot/results.json" download>Full results · JSON ↓</a><a href="/research/files/PILOT_STUDY.md" download>Scientific note · Markdown ↓</a></div><section class="study-box"><p class="eyebrow">THE PHYSICAL IDEA TO CARRY FORWARD</p><h2>Model the recording history before inferring the ancient field.</h2><p>The data support this as a research strategy, not yet as a demonstrated geological history. Copernicus and Huygens provide comparatively stable contrasts to explain. Newton tests sensitivity to the surface-unit mixture; Schiaparelli tests spatial scale and missing comparable terrain.</p><p>The next discriminating evidence is a dated link between a magnetic carrier and an alteration or heating event, coupled to regional source geometry and adequate observation coverage. A model should then predict a region withheld from fitting. Adding unconstrained histories to explain every map would not constitute a test.</p><a href="/research/pilot/hypotheses">Read the predictions and failure criteria →</a></section>'''

content={
    'start':('What happened to the magnetic record?','A first study connecting orbital observations, geological context and the histories recorded by Martian rocks.',start),
    'regions':('One region at a time.','Choose a case. Change altitude. Then check whether the contrast survives a different comparison.',regions),
    'hypotheses':('Three histories. Different predictions.','Separate what could have happened from what would be needed to demonstrate it.',hypotheses),
    'method':('A comparison you can inspect.','The source data, calculation choices and limits of the test are part of the result.',method),
    'results':('The comparison changes the interpretation.','Computed regional results, followed by what they do—and do not—tell us about Mars.',results),
}
out=ROOT/'web/pilot';out.mkdir(exist_ok=True)
for stem,(title,lead,body) in content.items():
    (out/f'{stem}.html').write_text(page(stem,title,lead,body))
    print(stem)
